def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_coop_rate = opp_c / n
    last_me, last_opp = history[-1]

    forgive = 0
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'C':
            forgive += 1

    recent_opp_d = 0
    for i in range(max(0, n-6), n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    if forgive >= 2 and recent_opp_d <= 2:
        if last_opp == 'D':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.25:
                return 'D'
            return 'C'

    if last_opp == 'C':
        return 'C'
    else:
        recent_opp_d_5 = 0
        for i in range(max(0, n-5), n):
            if history[i][1] == 'D':
                recent_opp_d_5 += 1
        if recent_opp_d_5 <= 1 and opp_coop_rate > 0.5:
            if rng.random() < 0.3:
                return 'C'
        elif recent_opp_d_5 <= 2 and opp_coop_rate > 0.3:
            if rng.random() < 0.1:
                return 'C'
        return 'D'
